use std::rc::Rc;use std::cell::RefCell;struct Codec;impl Codec{fn new()->Self{Self}fn serialize(&self,r:Option<Rc<RefCell<TreeNode>>>)->String{fn f(n:&Option<Rc<RefCell<TreeNode>>>,o:&mut String){if let Some(x)=n{let b=x.borrow();o.push_str(&format!("{} ",b.val));f(&b.left,o);f(&b.right,o)}else{o.push_str("# ")}}let mut o=String::new();f(&r,&mut o);o}fn deserialize(&self,data:String)->Option<Rc<RefCell<TreeNode>>>{fn f<'a,I:Iterator<Item=&'a str>>(it:&mut I)->Option<Rc<RefCell<TreeNode>>>{let x=it.next()?;if x=="#"{return None}let v=x.parse().unwrap();Some(Rc::new(RefCell::new(TreeNode{val:v,left:f(it),right:f(it)})))}f(&mut data.split_whitespace())}}
